    while (position < end) {
      const entry = script[position++];
      if (entry.op !== 'insert') {
        hunk.oldLines++;
        oldPosition++;
      }
      if (entry.op !== 'delete') {
        hunk.newLines++;
        newPosition++;
      }
      const marker = entry.op === 'equal' ? ' ' : entry.op === 'delete' ? '-' : '+';
