'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const row = new Uint32Array(b.length + 1);
  for (const line of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const previous = row[j];
      row[j] = line === b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
      diagonal = previous;
    }
  }
  return row[b.length];
}

function expectedHunks(script, context) {
  const ranges = [];
  for (let i = 0; i < script.length; i++) {
    if (script[i].op === 'equal') continue;
    const start = Math.max(0, i - context);
    const end = Math.min(script.length, i + context + 1);
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous[1]) previous[1] = Math.max(previous[1], end);
    else ranges.push([start, end]);
  }
  return ranges.map(([start, end]) => {
    const before = script.slice(0, start);
    const body = script.slice(start, end);
    const oldLines = body.filter(e => e.op !== 'insert').length;
    const newLines = body.filter(e => e.op !== 'delete').length;
    return {
      oldStart: before.filter(e => e.op !== 'insert').length + (oldLines ? 1 : 0),
      oldLines,
      newStart: before.filter(e => e.op !== 'delete').length + (newLines ? 1 : 0),
      newLines,
      lines: body.map(e => ({ equal: ' ', delete: '-', insert: '+' }[e.op]) + e.line),
    };
  });
}

function check(a, b, contexts) {
  Object.freeze(a);
  Object.freeze(b);
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  let inserted = false;
  for (const entry of script) {
    assert.ok(['equal', 'insert', 'delete'].includes(entry.op));
    if (entry.op === 'equal') inserted = false;
    if (entry.op === 'delete') assert.equal(inserted, false);
    if (entry.op === 'insert') inserted = true;
  }
  assert.deepEqual(diffLines(a, b), script);
  for (const context of contexts) {
    const hunks = unifiedHunks(a, b, { context });
    assert.deepEqual(hunks, expectedHunks(script, context));
    for (const hunk of hunks) {
      Object.freeze(hunk.lines);
      Object.freeze(hunk);
    }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
  }
}

test('exhaustive minimality, ordering, coordinates, merging and roundtrips', () => {
  const arrays = [[]];
  let level = [[]];
  for (let length = 1; length <= 4; length++) {
    level = level.flatMap(a => ['', 'a', 'b'].map(line => [...a, line]));
    arrays.push(...level);
  }
  for (const a of arrays) for (const b of arrays) check(a, b, [0, 1, 2, 3]);
});

test('seeded repeated/prefix-bearing line roundtrips', () => {
  let state = 0x12345678;
  const random = n => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return (state >>> 0) % n;
  };
  const alphabet = ['', 'a', 'a', '+text', '-text', ' text', '\r', '雪'];
  for (let i = 0; i < 500; i++) {
    const a = Array.from({ length: random(35) }, () => alphabet[random(alphabet.length)]);
    const b = Array.from({ length: random(35) }, () => alphabet[random(alphabet.length)]);
    check(a, b, [0, 1, 3, 40]);
  }
});

test('zero-line coordinates and original-coordinate offset application', () => {
  assert.deepEqual(unifiedHunks([], ['+'], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['++'] },
  ]);
  assert.deepEqual(unifiedHunks(['-'], [], { context: 0 }), [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['--'] },
  ]);
  const original = Object.freeze(['a', 'b', 'c', 'd', 'e']);
  const hunks = [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 2, lines: ['+x', '+y'] },
    { oldStart: 2, oldLines: 2, newStart: 4, newLines: 1, lines: ['-b', '-c', '+z'] },
    { oldStart: 5, oldLines: 1, newStart: 5, newLines: 0, lines: ['-e'] },
    { oldStart: 5, oldLines: 0, newStart: 6, newLines: 1, lines: ['+q'] },
  ];
  assert.deepEqual(applyHunks(original, hunks), ['x', 'y', 'a', 'z', 'd', 'q']);
  const copy = applyHunks(original, []);
  assert.deepEqual(copy, original);
  assert.notEqual(copy, original);
});

test('malformed, mismatched, out-of-order and overlapping hunks report index', () => {
  const a = ['a', 'b', 'c'];
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const invalid = [
    null, {}, { ...valid, oldStart: 0 }, { ...valid, newStart: 0 },
    { ...valid, oldStart: -1 }, { ...valid, oldStart: 1.5 },
    { ...valid, newStart: NaN }, { ...valid, oldLines: Infinity },
    { ...valid, newLines: -1 }, { ...valid, oldStart: 5 },
    { ...valid, oldLines: 4 }, { ...valid, oldLines: 0 },
    { ...valid, newLines: 0 }, { ...valid, newStart: 3 },
    { ...valid, lines: ['-wrong', '+B'] },
    { ...valid, lines: [' wrong'] }, { ...valid, lines: ['?b'] },
    { ...valid, lines: [''] }, { ...valid, lines: [null] },
    { ...valid, lines: 'not an array' },
    { ...valid, lines: ['-b', '-c', '+B'] },
  ];
  for (const hunk of invalid) {
    assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  }
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { ...valid, oldStart: 1, newStart: 1 }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 3, oldLines: 1, newStart: 4, newLines: 1, lines: [' c'] }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, null), /hunk 0 does not apply/);
  for (const context of [-1, 0.5, NaN, Infinity]) {
    assert.throws(() => unifiedHunks(a, a, { context }), RangeError);
  }
});

test('20,000-line small changes stay below one second end-to-end', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? 'repeat' : `line ${i}`);
    const b = a.slice();
    b.splice(0, 0, 'top');
    b.splice(7000, 1, 'replacement');
    b.splice(14000, 2);
    b.push('bottom');
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const output = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.deepEqual(output, b);
